pub fn generate() -> Result<Self, StateOnlyAttemptEntropyError> {
    for _ in 0..ENTROPY_RETRY_LIMIT {
        let mut bytes = Zeroizing::new([0u8; 96]);
        getrandom::fill(bytes.as_mut())?;

        let mut mask_nonce = [0u8; 32];
        let mut field_mask_entropy = Zeroizing::new([0u8; 32]);
        let mut leaf_salt_seed = Zeroizing::new([0u8; 32]);
        mask_nonce.copy_from_slice(&bytes[..32]);
        field_mask_entropy.copy_from_slice(&bytes[32..64]);
        leaf_salt_seed.copy_from_slice(&bytes[64..]);

        if mask_nonce != [0; 32] && *field_mask_entropy != [0; 32] && *leaf_salt_seed != [0; 32]
        {
            return Ok(Self {
                mask_nonce,
                field_mask_entropy,
                leaf_salt_seed,
            });
        }
    }
    Err(StateOnlyAttemptEntropyError::RepeatedZeroBlock)
}

/// Generate fresh private attempt entropy for a preselected public nonce.
///
/// A deployed proof binds this nonce to the proof-account address. Clients
/// therefore generate the account keypair first and pass its public key
/// here. The public nonce only needs to be unique; both secret seeds still
/// come independently from the operating system and are zeroized on drop.
pub fn generate_for_mask_nonce(
    mask_nonce: [u8; 32],
) -> Result<Self, StateOnlyAttemptEntropyError> {
    if mask_nonce == [0; 32] {
        return Err(StateOnlyAttemptEntropyError::RepeatedZeroBlock);
    }
    for _ in 0..ENTROPY_RETRY_LIMIT {
        let mut bytes = Zeroizing::new([0u8; 64]);
        getrandom::fill(bytes.as_mut())?;

        let mut field_mask_entropy = Zeroizing::new([0u8; 32]);
        let mut leaf_salt_seed = Zeroizing::new([0u8; 32]);
        field_mask_entropy.copy_from_slice(&bytes[..32]);
        leaf_salt_seed.copy_from_slice(&bytes[32..]);
        if *field_mask_entropy != [0; 32] && *leaf_salt_seed != [0; 32] {
            return Ok(Self {
                mask_nonce,
                field_mask_entropy,
                leaf_salt_seed,
            });
        }
    }
    Err(StateOnlyAttemptEntropyError::RepeatedZeroBlock)

    pub fn reserve_and_build_pool_v1_pair_forest_mask_material_v1(
        mut self,
        hash: HashFn,
        precommit_binding: [u8; 32],
        context: StateOnlyHidingContext,
        nonce_store: &mut impl StateOnlyMaskNonceStore,
    ) -> Result<(ReservedStateOnlyAttemptSecrets, StateOnlyMaskMaterial), StateOnlyMaskBuildError>
    {
        if context.mask_nonce != self.mask_nonce
            || context.mask_layout_fingerprint
                != PINNED_POOL_V1_PAIR_FOREST_RELATION_FREE_MASK_FINGERPRINT_V1
            || context.layout_factor_fingerprint
                != PINNED_POOL_V1_PAIR_FOREST_HIDING_LAYOUT_FACTOR_FINGERPRINT_V1
        {
            return Err(StateOnlyMaskBuildError::Layout);
        }
        if !nonce_store.reserve(context.statement_digest, context.mask_nonce) {
            return Err(StateOnlyMaskBuildError::ReusedMaskNonce);
        }
        let mut pre_reserved = PreReservedNonce {
            statement_digest: context.statement_digest,
            mask_nonce: context.mask_nonce,
            consumed: false,
        };
        let material = build_pool_v1_pair_forest_mask_material_v1_from_entropy_ref(
            hash,
            precommit_binding,
            context,
            &self.field_mask_entropy,
            &mut pre_reserved,
        )?;
        if !pre_reserved.consumed {
            return Err(StateOnlyMaskBuildError::ReusedMaskNonce);
        }
        let source_mask_seed = Zeroizing::new(hash(&[
            POOL_V1_SOURCE_SEED_DOMAIN,
            &precommit_binding,
            &context.encode(),
            self.field_mask_entropy.as_ref(),
        ]));
        self.field_mask_entropy.zeroize();
        Ok((
            ReservedStateOnlyAttemptSecrets {
                mask_nonce: self.mask_nonce,
                precommit_binding,
                reserved_context: context,
                leaf_salt_seed: self.leaf_salt_seed,
                source_mask_seed,
            },
            material,
        ))
    }
}

struct PreReservedNonce {
    statement_digest: [u8; 32],

    pub fn last_error(&self) -> Option<io::ErrorKind> {
        self.last_error
    }

    fn reservation_path(&self, mask_nonce: &[u8; 32]) -> PathBuf {
        // The nonce is burned globally within this wallet ledger, even if a
        // caller tries to reuse it under a different statement digest.
        let mut hasher = Sha256::new();
        hasher.update(ATTEMPT_RESERVATION_DOMAIN);
        hasher.update(mask_nonce);
        let digest: [u8; 32] = hasher.finalize().into();
        let mut name = String::with_capacity(69);
        for byte in digest {
            use std::fmt::Write as _;
            write!(&mut name, "{byte:02x}").expect("writing to String cannot fail");
        }
        name.push_str(".burn");
        self.directory.join(name)
    }

    pub fn reserve_fallible(
        &mut self,
        statement_digest: [u8; 32],
        mask_nonce: [u8; 32],
    ) -> io::Result<bool> {
        self.last_error = None;
        let path = self.reservation_path(&mask_nonce);
        let mut options = OpenOptions::new();
        options.write(true).create_new(true);
        #[cfg(unix)]
        options.mode(0o600);
        let mut file = match options.open(path) {
            Ok(file) => file,
            Err(error) if error.kind() == io::ErrorKind::AlreadyExists => return Ok(false),
            Err(error) => return Err(error),
        };

        // A partially written file is still a burned nonce. Never remove it
        // on failure.
        file.write_all(RESERVATION_MAGIC)?;
        file.write_all(&statement_digest)?;
        file.write_all(&mask_nonce)?;
        file.sync_all()?;
        sync_directory(&self.directory)?;
        Ok(true)
    }
}

impl StateOnlyMaskNonceStore for DurableStateOnlyMaskNonceStore {
    fn reserve(&mut self, statement_digest: [u8; 32], mask_nonce: [u8; 32]) -> bool {
        match self.reserve_fallible(statement_digest, mask_nonce) {
            Ok(reserved) => reserved,
            Err(error) => {
                self.last_error = Some(error.kind());
                false
            }

/// Secure-source P3 host API. Callers must supply OS-generated attempt
/// secrets and a durable nonce ledger; successful reservations happen before
/// mask derivation and leaf-salt derivation. This is still an UNPROVED
/// protocol: fresh entropy alone does not establish zero knowledge.
pub fn prove_masked_attempt(
    public:Public<'_>,
    compiled:&PoolV1PairForestMergedC1CompilationV1,
    variant:Variant,
    hash:HashFn,
    attempt:StateOnlyAttemptSecrets,
    nonce_store:&mut DurableStateOnlyMaskNonceStore,
)->Result<(Vec<u8>,MaskedFixtureAudit),Error> {
    let public_bytes=public.public_bytes().map_err(|_|Error::Semantic)?;
    let context=StateOnlyHidingContext::pool_v1_pair_forest_v1(hash(&[&public_bytes]),attempt.mask_nonce());
    let binding=hash(&[b"UNPROVED:R1:P3:PRIVATE-ATTEMPT",&public_bytes,&[variant.tag()],&context.encode()]);
    prove_masked_with_attempt(public,compiled,variant,hash,context,binding,attempt,nonce_store)
}

fn prove_masked_with_attempt(
    public:Public<'_>,
    compiled:&PoolV1PairForestMergedC1CompilationV1,
    variant:Variant,
    hash:HashFn,
    context:StateOnlyHidingContext,
    binding:[u8;32],
    attempt:StateOnlyAttemptSecrets,
    nonce_store:&mut impl StateOnlyMaskNonceStore,
)->Result<(Vec<u8>,MaskedFixtureAudit),Error> {
    let (reserved,material)=attempt.reserve_and_build_pool_v1_pair_forest_mask_material_v1(hash,binding,context,nonce_store).map_err(mask_error)?;
    #[cfg(all(test,feature="r1p-check"))]
    if test_hooks::forced_exhaustion(reserved.mask_nonce()) { return Err(mask_error(StateOnlyMaskBuildError::MaskSampleExhausted)); }
    let mut noised_c1=compiled.semantic_c1.clone();
    let applied=apply_pool_v1_pair_forest_mask_material_v1(&mut noised_c1,material).map_err(|_|Error::Semantic)?;
    let masks=pool_v1_pair_forest_copy_active_row_masks_v1().map_err(|_|Error::Semantic)?;
    let d: [K;1024]=reserved.derive_pool_v1_pair_forest_zero_factor_d(hash,context).map_err(mask_error)?.try_into().map_err(|_|Error::Semantic)?;

/// exhausted (`exh`, R1Z/GamesR1P.lean:164, 184) and moves to the next one.
/// With the retry loop, `MaskSampleExhausted` from either expander is
/// therefore a rejected attempt; every other mask error still aborts. Without
/// the loop (`r1p-check` off) behaviour is unchanged.
fn mask_error(e:StateOnlyMaskBuildError)->Error {
    #[cfg(feature="r1p-check")]
    if e==StateOnlyMaskBuildError::MaskSampleExhausted { return Error::Rejected; }
    let _=e;
    Error::Semantic
}

/// D38.3 retry loop with fresh OS attempt secrets for every attempt.
#[cfg(feature="r1p-check")]
pub fn prove_masked_retrying(
    public:Public<'_>,
    compiled:&PoolV1PairForestMergedC1CompilationV1,
    variant:Variant,
    hash:HashFn,
    nonce_store:&mut DurableStateOnlyMaskNonceStore,
)->Result<RetriedProof,Error> {
    prove_masked_retrying_with(public,compiled,variant,hash,nonce_store,|_|StateOnlyAttemptSecrets::generate().map_err(|_|Error::Entropy))
}

/// D38.3 retry loop. `next_attempt(k)` must return fresh OS-generated secrets
/// for attempt k; a client that binds the nonce to the proof-account address
/// (D38.4) generates a fresh account keypair per attempt and calls
/// `StateOnlyAttemptSecrets::generate_for_mask_nonce` with its public key.
///
/// Each attempt durably burns its nonce in `nonce_store` before any mask or
/// salt is derived (`reserve_and_build_…`). As in Lean `realGameP`
/// (R1Z/GamesR1P.lean:184: accept on `P ∧ VR1 ∧ ¬ exh`), an attempt is
/// rejected when its challenges fail P_R1, when χ is a LogUp pole (`¬ VR1`,
/// LOG D40.3, D73.4.1), or when its mask decode is exhausted (`exh`,
/// D73.4.2). Each returns the same detail-free `Error::Rejected` before any
/// proof byte exists; its secrets are dropped (zeroized), it consumes one of
/// the `ATTEMPT_CAP` attempts, and nothing about it is returned or logged.
/// After `ATTEMPT_CAP` rejections the result is `AttemptsExhausted` and
/// nothing is published (Lean's fixed `failView`, R1Z/GamesR1P.lean:185).
/// Any other error aborts.
#[cfg(feature="r1p-check")]
pub fn prove_masked_retrying_with(
    public:Public<'_>,
    compiled:&PoolV1PairForestMergedC1CompilationV1,
    variant:Variant,
    hash:HashFn,
    nonce_store:&mut DurableStateOnlyMaskNonceStore,
    mut next_attempt:impl FnMut(usize)->Result<StateOnlyAttemptSecrets,Error>,
)->Result<RetriedProof,Error> {
    if variant!=Variant::S2 { return Err(Error::Semantic); }
    for k in 0..ATTEMPT_CAP {
        let attempt=next_attempt(k)?;
        match prove_masked_attempt(public,compiled,variant,hash,attempt,nonce_store) {
            Ok((proof,audit))=>return Ok(RetriedProof{proof,audit,attempts:k+1}),
            Err(Error::Rejected)=>continue,
            Err(e)=>return Err(e),
        }
    }
    Err(Error::AttemptsExhausted)
}

